<?php
declare(strict_types=1);
ini_set('session.save_path',__DIR__.'/../includes/runtime');require_once __DIR__.'/../includes/auth.php';
foreach([6,7,9,10] as $gradeNumber){$mediums=[];$m=db()->prepare("SELECT DISTINCT l.medium FROM lessons l JOIN grades g ON g.id=l.grade_id WHERE g.grade_number=? AND l.status='active' AND l.content_source='textbook' ORDER BY FIELD(l.medium,'English','Sinhala','Tamil')");$m->bind_param('i',$gradeNumber);$m->execute();foreach($m->get_result() as $item)$mediums[]=(string)$item['medium'];foreach($mediums as $testMedium){$student=query_one("SELECT u.id,u.full_name,u.username,u.email,u.phone,u.phone_verified_at,u.school_name,u.district,u.grade_id,u.medium,u.preferred_language,u.profile_image,u.subscription_expires_at,u.referral_promoter_id,u.referral_code_used,u.status FROM users u JOIN grades g ON g.id=u.grade_id WHERE g.grade_number=? AND u.medium=? AND u.status='active' ORDER BY u.id LIMIT 1",'is',[$gradeNumber,$testMedium]);if(!$student){$grade=query_one('SELECT id FROM grades WHERE grade_number=?','i',[$gradeNumber]);$student=['id'=>0,'full_name'=>'Rendering Test','username'=>'render_test','email'=>null,'phone'=>null,'phone_verified_at'=>null,'school_name'=>'Local Test','district'=>'Colombo','grade_id'=>(int)$grade['id'],'medium'=>$testMedium,'preferred_language'=>medium_language($testMedium),'profile_image'=>null,'subscription_expires_at'=>null,'referral_promoter_id'=>null,'referral_code_used'=>null,'status'=>'active'];}$lesson=query_one("SELECT l.id,q.id quiz_id FROM lessons l JOIN quizzes q ON q.lesson_id=l.id AND q.status='active' WHERE l.grade_id=? AND l.status='active' AND l.content_source='textbook' AND l.medium=? ORDER BY l.id,q.id LIMIT 1",'is',[(int)$student['grade_id'],$testMedium]);if(!$lesson)throw new RuntimeException("No Grade $gradeNumber $testMedium lesson exists.");$id=(int)$lesson['id'];$lessonUrl='http://localhost/educhat/student/lesson.php?id='.$id;$quizUrl='http://localhost/educhat/student/quiz.php?id='.(int)$lesson['quiz_id'];$sessionId='verifygrade'.$gradeNumber.bin2hex(random_bytes(5));$run=static function(string $url)use($sessionId):string{$command=['curl.exe','-sS','-b','PHPSESSID='.$sessionId,$url];$pipes=[];$process=proc_open($command,[['pipe','r'],['pipe','w'],['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);fclose($pipes[0]);$html=(string)stream_get_contents($pipes[1]);$error=(string)stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);if($exit!==0)throw new RuntimeException(trim($error));return $html;};$sessionData='user|'.serialize($student).'lang|'.serialize(medium_language($testMedium));$apacheSession='C:/xampp/tmp/sess_'.$sessionId;if(file_put_contents($apacheSession,$sessionData)===false)throw new RuntimeException('Could not prepare the Apache test session.');$lessonHtml=$run($lessonUrl);if(!str_contains($lessonHtml,'Quick Challenge')||!str_contains($lessonHtml,'SHORT NOTES')&&!str_contains($lessonHtml,'කෙටි සටහන්')&&!str_contains($lessonHtml,'சுருக்கக் குறிப்புகள்'))throw new RuntimeException("Grade $gradeNumber $testMedium lesson page did not render the new notes/challenge.");$quizHtml=$run($quizUrl);if(!str_contains($quizHtml,'Question 1 of 5')||!str_contains($quizHtml,'Quick Challenge'))throw new RuntimeException("Grade $gradeNumber $testMedium Quick Challenge did not render five questions.");@unlink($apacheSession);echo "PASS: Grade $gradeNumber $testMedium lesson notes and five-question Quick Challenge rendered.\n";}}
